    ) as t(name_fr, name_en, size, ctype, alignment, ac, armor_detail, hp, hit_dice, speed, abilities, saves, skills, vuln, res, imm, cond_imm, senses, languages, cr, xp, pb, init, traits, actions, bonus_actions, reactions, legendary)
  loop
    if not exists (
      select 1 from public.translations tr
       where tr.entity_type = 'creature' and tr.field_name = 'name' and tr.locale = 'en' and tr.value = rec.name_en
    ) then
      insert into public.creatures (size, creature_type, alignment, armor_class, armor_detail, hit_points, hit_dice, speed,
                                    ability_scores, saving_throws, skills, damage_vulnerabilities, damage_resistances,
                                    damage_immunities, condition_immunities, senses, languages, challenge_rating,
                                    experience_points, proficiency_bonus, initiative_bonus, traits, actions, bonus_actions,
                                    reactions, legendary_actions, source)
        values (rec.size, rec.ctype, rec.alignment, rec.ac, rec.armor_detail, rec.hp, rec.hit_dice, rec.speed,
                rec.abilities, rec.saves, rec.skills, rec.vuln, rec.res, rec.imm, rec.cond_imm, rec.senses, rec.languages,
                rec.cr, rec.xp, rec.pb, rec.init, rec.traits, rec.actions, rec.bonus_actions, rec.reactions, rec.legendary,
                'SRD 5.2 (Manuel des Monstres 2024)')
        returning id into v_id;
      insert into public.translations (entity_type, entity_id, field_name, locale, value) values
        ('creature', v_id::text, 'name', 'fr', rec.name_fr),
        ('creature', v_id::text, 'name', 'en', rec.name_en);
      v_inserted := v_inserted + 1;
    end if;
  end loop;
  raise notice 'créatures insérées : %', v_inserted;
end $$;
